/* init: add vgpr [0...22) to pool */
/* init: add vgpr [538...1238) to pool */
/* init: add vgpr [22...534) to pool */
/* init: add agpr [0...0) to pool */

/******************************************/
/* Local Read Addresses                   */
/******************************************/

/* local read addresses: tile assignments a/b */
/* lr0I */
s_nop 0
s_set_vgpr_msb 8                                   // src0: 0, src1: 2, src2: 0, dst: 0
v_and_b32 v1, 31, v[vgprSerial-512]                // 0. thread id in wave: wtid = tid % wavelength(32)
s_set_vgpr_msb 2048                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v0, 15, v1                               // 1. N offset: nIdx = wtid % MI_N(16)
v_lshlrev_b32 v0, 7, v0                            // 1. N offset: nOffset = nIdx * nStride(128)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
v_lshlrev_b32 v0, 3, v0                            // 4. apply VectorWidth: bnOffset = bnOffset * vw(8)
v_lshrrev_b32 v1, 4, v1                            // 5. K offset: kIdx = wtid / (MIN(16) * MIBB(1))
v_lshl_add_u32 v0, v1, 5, v0                       // 5. K offset: lrKOffset = kIdx * mStride(32); 6. offset in wave: lrOffset = bnOffset + lrKOffset
s_set_vgpr_msb 8                                   // src0: 0, src1: 2, src2: 0, dst: 0
v_lshrrev_b32 v4, 5, v[vgprSerial-512]             // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(32)
s_set_vgpr_msb 2048                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v4, 1, v4                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
v_lshl_add_u32 v0, v4, 15, v0                      // 7. wave offset in M dimen: wOffset = wtid0 * W0Stride(32768); 7. final local read offset: flrOffset = lrOffset + WOffset
/* lr0I */
s_set_vgpr_msb 8                                   // src0: 0, src1: 2, src2: 0, dst: 0
v_and_b32 v2, 31, v[vgprSerial-512]                // 0. thread id in wave: wtid = tid % wavelength(32)
s_set_vgpr_msb 2048                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v1, 31, v2                               // 1. N offset: nIdx = wtid % MI_N(32)
v_lshlrev_b32 v1, 3, v1                            // 1. N offset: nOffset = nIdx * nStride(8)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
v_lshlrev_b32 v1, 3, v1                            // 4. apply VectorWidth: bnOffset = bnOffset * vw(8)
s_set_vgpr_msb 8                                   // src0: 0, src1: 2, src2: 0, dst: 0
v_lshrrev_b32 v3, 5, v[vgprSerial-512]             // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(32)
s_set_vgpr_msb 2048                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v3, 1, v3                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
v_lshl_add_u32 v1, v3, 11, v1                      // 7. wave offset in M dimen: wOffset = wtid0 * W0Stride(2048); 7. final local read offset: flrOffset = lrOffset + WOffset
/* lr1J */
s_set_vgpr_msb 8                                   // src0: 0, src1: 2, src2: 0, dst: 0
v_and_b32 v3, 31, v[vgprSerial-512]                // 0. thread id in wave: wtid = tid % wavelength(32)
s_set_vgpr_msb 2048                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v2, 15, v3                               // 1. N offset: nIdx = wtid % MI_N(16)
v_lshlrev_b32 v2, 7, v2                            // 1. N offset: nOffset = nIdx * nStride(128)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
v_lshlrev_b32 v2, 1, v2                            // 4. apply VectorWidth: bnOffset = bnOffset * vw(2)
v_lshrrev_b32 v3, 4, v3                            // 5. K offset: kIdx = wtid / (MIN(16) * MIBB(1))
v_lshl_add_u32 v2, v3, 5, v2                       // 5. K offset: lrKOffset = kIdx * mStride(32); 6. offset in wave: lrOffset = bnOffset + lrKOffset
s_set_vgpr_msb 8                                   // src0: 0, src1: 2, src2: 0, dst: 0
v_lshrrev_b32 v6, 6, v[vgprSerial-512]             // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(64)
s_set_vgpr_msb 2048                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v6, 1, v6                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
v_lshl_add_u32 v2, v6, 12, v2                      // 7. wave offset in M dimen: wOffset = wtid0 * W0Stride(4096); 7. final local read offset: flrOffset = lrOffset + WOffset
/* lr1J */
s_set_vgpr_msb 8                                   // src0: 0, src1: 2, src2: 0, dst: 0
v_and_b32 v3, 31, v[vgprSerial-512]                // 0. thread id in wave: wtid = tid % wavelength(32)
s_set_vgpr_msb 2048                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v3, 15, v3                               // 1. N offset: nIdx = wtid % MI_N(16)
v_lshlrev_b32 v3, 3, v3                            // 1. N offset: nOffset = nIdx * nStride(8)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
v_lshlrev_b32 v3, 1, v3                            // 4. apply VectorWidth: bnOffset = bnOffset * vw(2)
s_set_vgpr_msb 8                                   // src0: 0, src1: 2, src2: 0, dst: 0
v_lshrrev_b32 v5, 6, v[vgprSerial-512]             // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(64)
s_set_vgpr_msb 2048                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v5, 1, v5                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
v_lshl_add_u32 v3, v5, 8, v3                       // 7. wave offset in M dimen: wOffset = wtid0 * W0Stride(256); 7. final local read offset: flrOffset = lrOffset + WOffset
s_set_vgpr_msb 8                                   // src0: 0, src1: 2, src2: 0, dst: 0
v_lshrrev_b32 v5, 4, v[vgprSerial-512]             // 8. (TileSpan wave-split) hiSel = tid / MI_dim(16)
s_set_vgpr_msb 2048                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v5, 1, v5                                // 8. (TileSpan wave-split) hi = (tid / MI_dim) & 1  (lower/upper half-wave)
v_lshl_add_u32 v3, v5, 9, v3                       // 8. (TileSpan wave-split) wave offset in N dimen: wOffset += hi * hiOffset(512); upper half-wave grabs partner block

/* local read addresses: final offsets a */
s_set_vgpr_msb 8                                   // src0: 0, src1: 2, src2: 0, dst: 0
v_lshrrev_b32 v4, 5, v[vgprSerial-512]             // 4 = Serial / 32
