s_set_vgpr_msb 32776                               // src0: 0, src1: 2, src2: 0, dst: 0
v_lshrrev_b32 v4, 8, v[vgprLocalReadAddrMXSA-512]  // Final Offset: padding 16 per block 256
s_set_vgpr_msb 2208                                // src0: 0, src1: 0, src2: 2, dst: 2
v_lshl_add_u32 v[vgprLocalReadAddrMXSA-512], v4, 4, v[vgprLocalReadAddrMXSA-512] // Final Offset: padding 16 per block 256

/* local read addresses: final offsets mxsb */
s_set_vgpr_msb 40968                               // src0: 0, src1: 2, src2: 0, dst: 0
v_lshrrev_b32 v0, 5, v[vgprSerial-512]             // 0 = Serial / 32
s_set_vgpr_msb 2048                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshrrev_b32 v0, 2, v0                            // LSU offset: Get LSU wave_id
s_mov_b32 s65, 1024                                // LSU offset: stride = lsuStride(8)*(MT1(128) + PAD1(0))
v_mul_lo_u32 v0, s65, v0                           // LSU offset: lsuoffset = wave_id*lsuStride*(MT1+PAD)
s_set_vgpr_msb 128                                 // src0: 0, src1: 0, src2: 0, dst: 2
v_add_nc_u32 v[vgprLocalReadAddrMXSB-512], v0, v3  // Final Offset: offset = (lro1+lsuoffset)*bpeDS
                                                   //  (bpe is 1, do nothing)

/* local read addresses: final offsets b */
s_set_vgpr_msb 32776                               // src0: 0, src1: 2, src2: 0, dst: 0
v_lshrrev_b32 v0, 5, v[vgprSerial-512]             // 0 = Serial / 32
s_set_vgpr_msb 2048                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshrrev_b32 v0, 2, v0                            // LSU offset: Get LSU wave_id
