v_cvt_f64_u32 v[0:1], s78                          // s[sgprWorkGroup1] = s87 / s78
v_rcp_f64 v[0:1], v[0:1]                           // s[sgprWorkGroup1] = s87 / s78
v_cvt_f64_u32 v[2:3], s87                          // s[sgprWorkGroup1] = s87 / s78
